import{_ as s,r as n,o as i,c,a as e,b as t,d as o,e as r}from"./app-rAiyxZ_I.js";const l={},d=e("nav",{class:"table-of-contents"},[e("ul")],-1),p=e("h1",{id:"_1、开启clash后git提交依然超时",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#_1、开启clash后git提交依然超时","aria-hidden":"true"},"#"),t(" 1、开启clash后git提交依然超时")],-1),h=e("p",null,"最近疯狂向github上面提交代码，每次提交都要超时，真的很烦人，关键还是开了梯子。",-1),g=e("p",null,"这里简单说一下用clash代理的情况下，设置github全局代理。clash一般默认的是7890的端口，我们只需要运行下面两个命令设置一下github的全局代理就可以了。",-1),_={href:"https://zhuanlan.zhihu.com/p/652905080",target:"_blank",rel:"noopener noreferrer"},u=r(`<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> config <span class="token parameter variable">--global</span> http.proxy http://127.0.0.1:7890
<span class="token function">git</span> config <span class="token parameter variable">--global</span> https.proxy https://127.0.0.1:7890
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="_2、提交git时提示需要账户名密码" tabindex="-1"><a class="header-anchor" href="#_2、提交git时提示需要账户名密码" aria-hidden="true">#</a> 2、提交git时提示需要账户名密码</h1><p>有一小部分时间，我们提交代码被要求输入用户名和密码，但是github已经取消了使用密码登录的功能，转而使用access token来登录，相当于将密码转换成access token。</p><p>在github网页端，点击个人头像可以设置。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>settings -&gt; Developer settings -&gt; Personal access tokens -&gt; Tokens
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><img src="https://gitee.com/jet5devil/typora-picture/raw/master/mac_img/202401181256509.png" alt="image-20240118125618933"></p><p>然后点击<code>new personal access token</code>, 进入之后，输入note（标题）， 选择失效时间，选择开启的权限（我一般除了删除的不勾，其他的都勾上了），最后点击生成，点击之后会出现一个access token码，这个就是在命令行里面输入的密码。</p><p><img src="https://gitee.com/jet5devil/typora-picture/raw/master/mac_img/202401181257968.png" alt="image-20240118125720915"></p>`,8);function m(b,v){const a=n("ExternalLinkIcon");return i(),c("div",null,[d,p,h,g,e("p",null,[t("参考开"),e("a",_,[t("clash后Git依然超时的解决方法"),o(a)])]),u])}const k=s(l,[["render",m],["__file","2024-01-18-提交github踩过的坑.html.vue"]]);export{k as default};
